func rk4_step(ode_fn, y, t, dt) = {

local k1 = -y

local k2 = -(y + 0.5*dt*k1)

local k3 = -(y + 0.5*dt*k2)

local k4 = -(y + dt*k3)
  y + dt/6 * (k1 + 2*k2 + 2*k3 + k4)
}

func solveODE(ode_fn, y0, t0, tf, dt, method) = {

local t = t0

local y = y0

local ts = [t0]

local ys = [y0]
  while (t < tf) {
    if (method === "euler") {
      y = y + dt * (-y)
    } else if (method === "rk4") {
      y = rk4_step(ode_fn, y, t, dt)
    } else if (method === "leapfrog") {

local v = -y * dt / 2
      y = y + v * dt
      v = v - y * dt / 2
      y = y + v
    }
    t = t + dt
    ts.add(t)
    ys.add(y)
  }
  {"ts": ts, "ys": ys}
}

