func karatsuba(a, b) = {
  if (a < 10 || b < 10) {
    a * b
  } else {

local n = max(floor(log(a)/log(10)) + 1, floor(log(b)/log(10)) + 1)

local m = floor(n / 2)

local p = 10 ^ m

local a1 = floor(a / p)

local a0 = a % p

local b1 = floor(b / p)

local b0 = b % p

local z0 = karatsuba(a0, b0)

local z2 = karatsuba(a1, b1)

local z1 = karatsuba(a0 + a1, b0 + b1) - z2 - z0
    z2 * p * p + z1 * p + z0
  }
}

