func validateDataContract(records, contract) = {

local violations =[]

local reqs = contract.get("required",[])

local unqs = contract.get("unique",[])

local rngs = contract.get("ranges", {})

local uniqueVals = {}
  for (u in unqs) { uniqueVals.set(u,[]) }

  for (i: 1 .. records.listLen()) {

local r = records[i]
    for (req in reqs) {
      if (!r.containsKey(req)) violations.add({"row": i, "error": "Missing required " _ req})
    }
    for (u in unqs) {

local val = r.get(u, "")
      if (uniqueVals.get(u, []).containsItem(val)) violations.add({"row": i, "error": "Duplicate " _ u})
      else { uniqueVals.get(u, []).add(val) }
    }
    for (k, limits in rngs) {
      if (r.containsKey(k)) {

local v = r.get(k, [])
        if (v < limits.get("min", []) || v > limits.get("max", [])) violations.add({"row": i, "error": "Range violation " _ k})
      }
    }
  }
  violations
}

