func bellmanFord(graph, start) = {

local dist = {}

local nodes = []
  for (u, edges in graph) {
    dist.set(u, 999999)
    if (!nodes.containsItem(u)) {
      nodes.add(u)
    }
    for (v, w in edges) {
      if (!nodes.containsItem(v)) {
        nodes.add(v)
        dist.set(v, 999999)
      }
    }
  }
  dist.set(start, 0)

local n = nodes.listLen()
  for (i: 1 .. n - 1) {
    for (u, edges in graph) {
      for (v, w in edges) {
        if (dist.get(u, 999999) + w < dist.get(v, 999999)) {
          dist.set(v, dist.get(u, 999999) + w)
        }
      }
    }
  }

local negCycle = false
  for (u, edges in graph) {
    for (v, w in edges) {
      if (dist.get(u, 999999) + w < dist.get(v, 999999)) {
        negCycle = true
      }
    }
  }
  if (negCycle) {
    println("Negative cycle detected")
  }
  dist
}
