local result = -1

local idx = -1
  for (i: 1 .. this.lruCache.listLen()) {
    if (this.lruCache[i][1] === key) {
      result = this.lruCache[i][2]
      idx = i
    }
  }
  if (idx != -1) {

local entry = this.lruCache[idx]
    this.lruCache.remove(idx)
    this.lruCache.add(entry)
  }
  result
}

func cache_put(key, val) {

local existing = -1
  for (i: 1 .. this.lruCache.listLen()) {
    if (this.lruCache[i][1] === key) {
      existing = i
    }
  }
  if (existing != -1) {
    this.lruCache.remove(existing)
  } else if (this.lruCache.listLen() >= this.lruCapacity) {
    this.lruCache.remove(1)
  }
  this.lruCache.add([key, val])
}

