        if (p.segment(j-1,1) === "." || p.segment(j-1,1) === sc) {
          dp[i+1][j+1] = dp[i+1][j+1] || dp[i][j+1]
        }
      } else if (pc === "." || pc === sc) {
        dp[i+1][j+1] = dp[i][j]
      }
    }
  }
  dp[m+1][n+1]
}
